<?php
require __DIR__ . '/_boot.php'; $pageTitle='Orders'; $pageDescription='From a thoughtful gesture to a bouquet at the door.';
$statuses=['pending','preparing','out_for_delivery','ready_for_pickup','completed','cancelled']; $filter=is_string($_GET['status'] ?? null) && in_array($_GET['status'],$statuses,true) ? $_GET['status'] : '';
$statement=db()->prepare('SELECT o.*,u.name AS customer_name FROM orders o JOIN users u ON u.id=o.user_id' . ($filter ? ' WHERE o.status=?' : '') . ' ORDER BY o.id DESC'); $statement->execute($filter ? [$filter] : []); $orders=$statement->fetchAll();
require dirname(__DIR__, 2) . '/templates/admin_header.php';
?>
<form method="get" class="filter-bar"><label for="status">Order status</label><select id="status" name="status"><option value="">All orders</option><?php foreach ($statuses as $status): ?><option value="<?= e($status) ?>" <?= $filter===$status ? 'selected' : '' ?>><?= e(admin_label($status)) ?></option><?php endforeach; ?></select><button class="button secondary" type="submit">Apply filter</button><?php if ($filter): ?><a href="<?= e(url('/admin/orders.php')) ?>">Clear</a><?php endif; ?></form>
<section class="panel"><?php if (!$orders): ?><div class="empty-state"><h2>No orders here yet.</h2><p><?= $filter ? 'Try another status or clear your filter.' : 'Completed customer checkouts will appear here.' ?></p></div><?php else: ?><div class="table-wrap"><table><thead><tr><th>Order</th><th>Customer</th><th>Fulfillment</th><th>Scheduled date</th><th>Status</th><th>Demo total</th><th></th></tr></thead><tbody><?php foreach ($orders as $order): ?><tr><td><a href="<?= e(url('/admin/order.php?id='.$order['id'])) ?>"><?= e($order['order_reference']) ?></a><small><?= e(substr($order['created_at'],0,10)) ?></small></td><td><?= e($order['customer_name']) ?></td><td><?= e(admin_label($order['fulfillment_method'])) ?></td><td><?= e($order['scheduled_date']) ?></td><td><span class="status status-<?= e($order['status']) ?>"><?= e(admin_label($order['status'])) ?></span></td><td><?= e(format_money($order['total'])) ?></td><td><a href="<?= e(url('/admin/order.php?id='.$order['id'])) ?>">View →</a></td></tr><?php endforeach; ?></tbody></table></div><?php endif; ?></section>
<?php require dirname(__DIR__, 2) . '/templates/admin_footer.php'; ?>
